//! Fixed public metadata for the project-owned module paths.
//!
//! Generated by the external qualification metadata generator from the pinned
//! project tables. Units and domains belong to each owning physical model.
//! Records and live configuration are served by their native families.

/// A finite public module value; no runtime numerical operation is performed.
#[derive(Clone, Copy, Debug)]
pub enum ModuleConstantValue {
    /// An absent optional metadata value.
    None,
    /// A dimensionless switch.
    Bool(bool),
    /// A selector or identifier.
    Integer(i64),
    /// A binary64 physical value in its model's documented units.
    Float(f64),
    /// A fixed name or description.
    Text(&'static str),
    /// An ordered immutable collection.
    Tuple(&'static [Self]),
    /// An ordered collection exposed as a fresh list at the binding boundary.
    List(&'static [Self]),
    /// An unordered set of fixed identifiers.
    Set(&'static [Self]),
    /// A finite mapping of fixed metadata values.
    Map(&'static [(Self, Self)]),
}

